// Aggregate GitHub activity from all three sources
const commits = $('Fetch Commits').all();
const issues = $('Fetch Closed Issues').all();
const prs = $('Fetch Pull Requests').all();
const config = $('Configuration').first().json;
const oneWeekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

// Filter commits from the past week
const recentCommits = commits.filter(item => {
  const date = new Date(item.json.commit?.committer?.date || item.json.commit?.author?.date);
  return date >= oneWeekAgo;
}).map(item => ({
  message: item.json.commit?.message?.split('\n')[0] || 'No message',
  author: item.json.commit?.author?.name || item.json.author?.login || 'Unknown',
  date: item.json.commit?.committer?.date || item.json.commit?.author?.date,
  sha: item.json.sha?.substring(0, 7)
}));

// Filter issues closed in the past week (exclude PRs)
const recentIssues = issues.filter(item => {
  if (item.json.pull_request) return false;
  const closedAt = new Date(item.json.closed_at);
  return closedAt >= oneWeekAgo;
}).map(item => ({
  title: item.json.title,
  number: item.json.number,
  author: item.json.user?.login || 'Unknown',
  labels: (item.json.labels || []).map(l => l.name)
}));

// Filter PRs merged in the past week
const recentPRs = prs.filter(item => {
  if (!item.json.merged_at) return false;
  const mergedAt = new Date(item.json.merged_at);
  return mergedAt >= oneWeekAgo;
}).map(item => ({
  title: item.json.title,
  number: item.json.number,
  author: item.json.user?.login || 'Unknown',
  merged_at: item.json.merged_at,
  additions: item.json.additions || 0,
  deletions: item.json.deletions || 0
}));

const reportDate = new Date().toISOString().split('T')[0];
const weekStart = oneWeekAgo.toISOString().split('T')[0];

return [{
  json: {
    repo: config.repo,
    language: config.language,
    webhook_url: config.webhook_url,
    api_key: config.api_key,
    report_date: reportDate,
    week_start: weekStart,
    commits: recentCommits,
    issues: recentIssues,
    pull_requests: recentPRs,
    stats: {
      total_commits: recentCommits.length,
      total_issues_closed: recentIssues.length,
      total_prs_merged: recentPRs.length,
      contributors: [...new Set([
        ...recentCommits.map(c => c.author),
        ...recentIssues.map(i => i.author),
        ...recentPRs.map(p => p.author)
      ])]
    }
  }
}];

