// Extract the summary text from the API response
const response = $input.first().json;
const config = $('Aggregate Activity').first().json;

let summary = '';
if (response.content && response.content.length > 0) {
  summary = response.content[0].text || '';
} else if (response.error) {
  summary = 'Error generating summary: ' + (response.error.message || JSON.stringify(response.error));
}

const formattedMessage = [
  `# Weekly Dev Summary: ${config.repo}`,
  `**Period:** ${config.week_start} to ${config.report_date}`,
  '',
  summary,
  '',
  '---',
  `**Stats:** ${config.stats.total_commits} commits | ${config.stats.total_issues_closed} issues closed | ${config.stats.total_prs_merged} PRs merged`,
  `**Contributors:** ${config.stats.contributors.join(', ') || 'None detected'}`
].join('\n');

return [{
  json: {
    summary: formattedMessage,
    repo: config.repo,
    webhook_url: config.webhook_url,
    report_date: config.report_date
  }
}];
